# Таблица штатного ИК-пульта H96 Pro Plus для загрузки в ядро (irkeymap).
#
# ⛔ КОДЫ ИЗМЕРЕНЫ НА ЖИВОЙ ПРИСТАВКЕ 23.08, а не взяты из прошивки.
# Это принципиально: /system/etc/remote.conf прошивки «Франкенштейн»
# описывает ДРУГОЙ пульт — там адрес 0x4040 и коды вида 0x11 (вправо),
# 0x10 (влево), 0x0d (ОК). Реальный пульт владельца присылает адрес 0x01
# и совсем другие команды. Эти приставки продаются с разными пультами,
# конфигурация в образе — от другой партии.
#
# Замер: getevent -lt /dev/input/event0, два независимых прогона совпали.
# Формат: <код кнопки, hex> <код клавиши Linux, dec>
#
# ⚠️ Перед загрузкой приёмник обязан быть в протоколе NEC:
#     echo nec > /sys/class/rc/rc0/protocols
# По умолчанию он в «сыром» режиме [lirc] и ничего не расшифровывает.

# --- навигация ---
0x116 103    # вверх          KEY_UP
0x11a 108    # вниз           KEY_DOWN
0x151 105    # влево          KEY_LEFT
0x150 106    # вправо         KEY_RIGHT
# ⚠️ ОК = 353 (KEY_SELECT), а НЕ 28 (KEY_ENTER). Проверено по
# /system/usr/keylayout/Generic.kl: «key 353 DPAD_CENTER», тогда как 28
# даёт просто ENTER. Телевизионный интерфейс ждёт центр крестовины, и
# без него Android даже не относит устройство к классу DPAD.
0x113 353    # ОК             KEY_SELECT → DPAD_CENTER

# --- основные ---
0x119 158    # назад          KEY_BACK
0x111 172    # домой          KEY_HOMEPAGE
0x14c 139    # меню           KEY_MENU
0x140 116    # выключение     KEY_POWER
0x100 183    # мышь           KEY_F13; consumes press/release in h96mouse

# --- громкость ---
0x118 115    # громкость +    KEY_VOLUMEUP
0x110 114    # громкость −    KEY_VOLUMEDOWN

# --- цифры (измерена только «2», остальные ждут замера) ---
0x10d 3      # 2              KEY_2

# ═══════════════════════════════════════════════════════════════════════
# ВТОРОЙ ПУЛЬТ — таблица из стоковой прошивки «Франкенштейн» (31.08.2026)
# ═══════════════════════════════════════════════════════════════════════
#
# Источник: /system/etc/remote.conf стоковой прошивки, заводской код
# 0x40400001 — то есть адрес пульта 0x4040, команды однобайтные.
# Здесь они записаны так, как их отдаёт ядро: (адрес << 8) | команда.
#
# Приставки этой модели продаются с разными пультами. Коды обоих
# держим в одной карте: чужие просто никогда не придут, а нужные
# сработают — какой бы пульт ни оказался в руках.
#
# Заодно отсюда берутся кнопки, которых у нас не было совсем:
# меню, поиск, список приложений, перемотка, цифры, отключение звука.

0x4043 113  # MUTE
0x4001 2  # No.1
0x4002 3  # No.2
0x4003 4  # No.3
0x4004 5  # No.4
0x4005 6  # No.5
0x4006 7  # No.6
0x4007 8  # No.7
0x4008 9  # No.8
0x4009 10  # No.9
0x4000 11  # N0.0
0x4045 125  # MENU
0x4042 1  # BACK/EXIT
0x400d 97  # ENTER/OK
0x4010 105  # LEFT
0x400b 103  # UP
0x400e 108  # DOWN
0x4011 106  # RIGHT
0x4018 115  # VOL+
0x4017 114  # VOL-
0x400c 14  # DEL
0x404d 116  # Power
0x401a 102  # home
0x4053 119  # media_pause
0x4044 52  # period
0x401e 123  # MEDIA_NEXT
0x401f 122  # MEDIA_PREVIOUS
0x40f1 140  # F10/factory_test
0x4054 150  # setting
0x4057 151  # PROG_YELLOW/EXPLORER
0x405b 152  # PROG_BLUE/MUSIC
0x405c 153  # ALLAPP
0x405d 154  # MEDIAPLAY
0x405e 159  # KODI
0x4066 217  # SEARCHSEARCH
